"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["90135"],{83526(e){e.exports=JSON.parse('{"id":"FUT-0352","slug":"beta","term":"Beta","also_known_as":[],"difficulty":"Intermediate","definition":"Beta is a measure of how much an investment\'s price tends to move compared with the overall market. A beta of 1 means it moves in line with the market; above 1 means it moves more, and below 1 means it moves less.","explanation":["Beta measures sensitivity to market movements, which reflects systematic risk. It is calculated from past returns, comparing how an investment moved with how a market index moved over the same period.","A share with a beta of 1.5 has historically tended to rise about 15% when the market rose 10%, and to fall about 15% when the market fell 10%. A share with a beta of 0.6 has tended to move only about 6% for every 10% move in the market. A beta near zero means the investment has moved largely independently of the market.","Companies in sectors such as technology or luxury goods often have higher betas, because their profits are sensitive to economic conditions. Utilities and consumer staples, such as food producers, often have lower betas.","Beta is a key input in the Capital Asset Pricing Model, which uses it to estimate a share\'s expected return and a company\'s cost of equity. Its limitations are that it is based on past data, which may not predict the future, and it captures only market-related risk, not risks specific to the company."],"note":"","total":1500,"prev":{"slug":"best-case-scenario","term":"Best-Case Scenario"},"next":{"slug":"bid-ask-spread","term":"Bid-Ask Spread"}}')}}]);